import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.CukOUUOK.js";const d=JSON.parse('{"title":"改革为什么总是被拖延——窗口、消耗战与制度债务：一个关于决策时机的分析框架","description":"本文可与另一篇《日子人的诞生》对照阅读，也可单独阅读。那篇讲的是人如何被塑形——一个结构怎样把人变成只想过日子的人；本文讲的是问题如何被拖大——同一个结构怎样把一个本来可以小修的问题，拖成只能整体推倒重来。两篇真正共享的…","frontmatter":{"title":"改革为什么总是被拖延——窗口、消耗战与制度债务：一个关于决策时机的分析框架","categories":"权力与制度","tags":["制度","权力","方法论","历史"],"description":"本文可与另一篇《日子人的诞生》对照阅读，也可单独阅读。那篇讲的是人如何被塑形——一个结构怎样把人变成只想过日子的人；本文讲的是问题如何被拖大——同一个结构怎样把一个本来可以小修的问题，拖成只能整体推倒重来。两篇真正共享的…","date":"2026-09-24T12:00:00.000Z","series":"脆性秩序","seriesOrder":2},"headers":[],"relativePath":"posts/2026-09-24-why-reforms-are-delayed.md","filePath":"posts/2026-09-24-why-reforms-are-delayed.md","lastUpdated":1790246770000}'),g={name:"posts/2026-09-24-why-reforms-are-delayed.md"};function a(e,o,p,i,l,h){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="改革为什么总是被拖延——窗口、消耗战与制度债务-一个关于决策时机的分析框架" tabindex="-1">改革为什么总是被拖延——窗口、消耗战与制度债务：一个关于决策时机的分析框架 <a class="header-anchor" href="#改革为什么总是被拖延——窗口、消耗战与制度债务-一个关于决策时机的分析框架" aria-label="Permalink to &quot;改革为什么总是被拖延——窗口、消耗战与制度债务：一个关于决策时机的分析框架&quot;">​</a></h1><blockquote><p>本文可与另一篇《日子人的诞生》对照阅读，也可单独阅读。那篇讲的是<strong>人如何被塑形</strong>——一个结构怎样把人变成只想过日子的人；本文讲的是<strong>问题如何被拖大</strong>——同一个结构怎样把一个本来可以小修的问题，拖成只能整体推倒重来。两篇真正共享的机制只有一条：<strong>迟滞</strong>，即约束解除之后，人和问题都不会沿原路返回。<br> 单独阅读本文不需要先读那篇。凡用到那篇的概念，本文都会在原地用一句话说明。</p></blockquote><h3 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h3><p>“为什么不改革”常被回答为”既得利益阻碍”。这个答案不算错，但它把结果当成了解释：既得利益既是拖延的产物，也是拖延的原因——真正需要解释的是这个闭环如何启动、为何难以停止。</p><p>本文的核心机制是<strong>两类成本在时间与可见性上的双重不对称</strong>：</p><ul><li><strong>改革的成本 C</strong> 是集中的、即时的、可见的——谁反对、反对多强，决策者当天就能看到；</li><li><strong>不改革的代价 B</strong> 是分散的、延迟的、不可见的——由无数人的小额损失累积，且要穿过层层过滤才能进入决策视野。</li></ul><p>决策者比较的是两个量，但看到的是 C 的现在时与 B 的过去时。<strong>即使 C &lt; B，只要 C 是硬信号而 B 是软信号，拖延仍然是理性的。</strong> 这解释了改革史的普遍现象：改革极少在问题温和时发生，而几乎总在危机之后发生——因为只有危机能把软信号硬化。</p><p>在此之上，本文展开四项机制，并明确其<strong>分工而非并列</strong>：消耗战解释集团间的僵持（主体为精英集团），个体不确定性解释大众层面的现状偏好（主体为个人），政策反馈解释阻力的内生增长（主体为时间），信息时滞解释决策者为何系统性地错判时机（主体为决策者）。四者作用于不同主体、在不同阶段主导——而信息时滞是其他三者的共同放大项。</p><p>本文的核心贡献是一项<strong>判据</strong>：<strong>若改革是必要的，则拖延期间后续改革的阻力趋势决定该拖延的性质——阻力下降为等待（近似期权），阻力上升为负债。</strong> 这是条件性命题，不含”改革是否必要”的判断；该判据在<strong>系统层</strong>与<strong>具体改革层</strong>分别适用，两者结论可能相反，须分别编码。第九节以苏联 1964–1985 为例，完整演示三分项阻力与财政调节变量的编码过程。</p><p>案例部分给出六类形态，<strong>刻意补入对照组</strong>（新加坡、越南）与政党型威权耐用性文献，并明确处理抽样逻辑：只用已知崩溃的样本归纳崩溃原因，是本文最需规避的错误。</p><p>本文另有两条推论值得前置。<strong>其一，窗口双向移动，但阻力单向累积</strong>——收紧是自动的、频繁而小幅，放松须有人决断、稀少而大幅；缅甸 2011–2015 开放与 2021 收回，足证方向并非单向，但每一次重新开窗都要比上一次推得更用力。其二，B 的硬化可以不靠危机，而靠<strong>制度化的信息生产</strong>（独立统计、审计、媒体）；由此可得一个限定命题——<strong>控制这些机构是”隐性债务”得以维持的必要条件，而非一切拖延的必要条件</strong>（民主世界的拖延提供了现成反例，见 8.4）。后一条给出两类拖延的区分：<strong>显性拖延</strong>由分配冲突与否决结构维持，<strong>隐性拖延</strong>由信息时滞维持，二者中危机的功能不同。</p><p>最后，拖延不是被动的空白，而是一套有手艺的主动实践——本文列出十种拖延技术及其可观测签名。</p><p>须说明本文的证据状态：全部命题目前仍是<strong>框架</strong>，而非结论。本文提出的拖延事件数据库（研究议程第 1 项）与信息时滞的识别设计（第 2 项）都尚未被执行。在这两项完成之前，本文提供的是<strong>可供检验的靶子</strong>，不是已被验证的发现。</p><h3 id="一、把-为什么不改革-从一个道德问题变成一个结构问题" tabindex="-1">一、把”为什么不改革”从一个道德问题变成一个结构问题 <a class="header-anchor" href="#一、把-为什么不改革-从一个道德问题变成一个结构问题" aria-label="Permalink to &quot;一、把”为什么不改革”从一个道德问题变成一个结构问题&quot;">​</a></h3><p>“为什么不改革”这句话通常带着道德重音：提问者预设了一个知道问题所在、有能力解决、却出于私利不去解决的主语。</p><p>这个预设在多数情形下是错的，而且错得有系统性。</p><p>更常见的情形是：<strong>每一个参与决策的人都认为现在不是时机。</strong> 财政部门的理由是当期压力太大；主管部门的理由是方案还不成熟；地方的理由是执行条件不具备；而反对者的理由——这条最有力——是改革会引发不可控的后果。每个人都拿得出具体的、可核实的理由，没有一个人需要出于恶意。</p><p>于是拖延不需要被任何人主张，它是所有人各自理性判断的汇总结果。</p><p>但这里必须先做一个术语澄清，否则后文会在同一个词上打滑。<strong>本文全程使用两种不同意义上的”理性”，并严格区分：</strong></p><ul><li><strong>决策者理性</strong>：在决策者<strong>可获得的信息集内</strong>的最优选择。本文绝大多数命题是关于它的。</li><li><strong>社会理性</strong>：以全部可得信息（包括被过滤掉的部分）计算的最优选择。</li></ul><p><strong>拖延的核心悖论正是这两种理性的分离</strong>：每一个拖延决定在决策者理性下是正当的，在社会理性下是次优的。混淆二者，就会把全文滑向”决策者愚蠢”这一本文明确反对的结论。</p><p>因此本文回答三个更窄的问题：</p><ol><li>拖延如何改变问题本身的性质？</li><li>什么条件下拖延是等待，什么条件下拖延是负债？——<strong>判据</strong></li><li>拖延是靠什么具体技术维持的？——<strong>手艺</strong></li></ol><h3 id="二、定义与判据" tabindex="-1">二、定义与判据 <a class="header-anchor" href="#二、定义与判据" aria-label="Permalink to &quot;二、定义与判据&quot;">​</a></h3><h3 id="_2-1-定义" tabindex="-1">2.1 定义 <a class="header-anchor" href="#_2-1-定义" aria-label="Permalink to &quot;2.1 定义&quot;">​</a></h3><p><strong>改革拖延</strong>：已知存在一项需要制度性变更的问题，决策系统在其可动员资源足以实施变更的条件下，持续以非变更方式应对，且该应对方式本身提高了未来变更的成本。</p><p>三个要件缺一不构成拖延：</p><ul><li><strong>已知</strong>：不是没发现，而是发现了没处理（这把拖延与信息失灵区分开）；</li><li><strong>有能力</strong>：不是资源不足，而是资源可用于他处（这把拖延与客观约束区分开）；</li><li><strong>提高了未来成本</strong>：这是最难验证、也最关键的一条。</li></ul><h3 id="_2-2-判据-条件性命题" tabindex="-1">2.2 判据（条件性命题） <a class="header-anchor" href="#_2-2-判据-条件性命题" aria-label="Permalink to &quot;2.2 判据（条件性命题）&quot;">​</a></h3><p>这是本文最重要的一条区分。</p><blockquote><p><strong>判据</strong>：<strong>若</strong>改革是必要的，<strong>则</strong>在拖延期间，后续实施该改革的阻力趋势决定该拖延的性质—— <strong>阻力下降</strong>（共识积累、技术成熟、财政改善、阻力集团萎缩）→ 拖延是<strong>等待</strong>，其性质接近一项期权； <strong>阻力上升</strong>（既得利益固化、期望抬升、财政恶化、组织完成适应性变形）→ 拖延是<strong>负债</strong>，每一年的等待都在追加本金。</p></blockquote><p><strong>为什么必须写成条件性命题？</strong> 因为判据自身无法回答”改革是否必要”。一个阻力持续下降的系统，可能是在为改革积累条件，也可能根本不需要改革——<strong>旧安排本身是良性的</strong>。这两种情形在判据上不可区分，因为”制度刚性”（阻力趋势）与”制度绩效”（是否需要改）是两个<strong>正交</strong>的维度。</p><p><strong>但”诚实留在框架之外”是有代价的，必须一并说明：判据因此在纸面上无法单独使用。</strong> 前件不可判定，则整个条件命题不可执行。第九节的演示对此的处理是径直假定”从指令性计划向有限市场协调过渡”是必要的，而 1975 年的苏联该改革是否必要是一个真实的反事实争论——”1975 年之前已可判定为负债”这一结论，完全悬在一个未被辩护的前提上。</p><p><strong>修补方式是给前件一个可操作的替代判据</strong>，不要求研究者裁决反事实：</p><blockquote><p><strong>必要性替代判据</strong>：若该系统自身曾在官方文件中承认该问题存在、或曾启动过针对该问题的变更而后中止，则”改革是必要的”这一前件视为成立。</p></blockquote><p>这是一个<strong>可观测的系统自认标准</strong>，不依赖研究者对反事实的判断。苏联案例中，1965 年柯西金改革的启动本身就是这一自认，前件因此有据；若无此类自认，则判据应被读作”<strong>若</strong>该改革必要，<strong>则</strong>……”的条件句，不作判定。</p><h3 id="_2-2b-聚合规则-三分项、平局裁决与来源检验" tabindex="-1">2.2b 聚合规则：三分项、平局裁决与来源检验 <a class="header-anchor" href="#_2-2b-聚合规则-三分项、平局裁决与来源检验" aria-label="Permalink to &quot;2.2b 聚合规则：三分项、平局裁决与来源检验&quot;">​</a></h3><p><strong>先要避开一处范畴错误</strong>：财政空间不是阻力。按 3.2 的表述，它是消耗战中的<strong>资源禀赋</strong>，决定的是”还能拖多久”，而非”拖下去阻力有多大”。把承受力与阻力塞进同一个指数，是判据的结构性混淆。</p><p>因此结构如下：<strong>阻力三分项</strong>（固化度、期望、方案空间）参与多数决；<strong>财政</strong>列为<strong>调节变量</strong>，不参与多数决，只用于估计窗口关闭的时点。多数决为三分项中至少两项同向。</p><p><strong>规则一：多数决。</strong> 三分项中至少两项同向，方可判定该拖延为”等待”或”负债”。</p><p><strong>规则二：平局裁决。</strong> 三分项中二对一、或出现弃权时，<strong>判为负债</strong>。理由是固化度与方案空间具有不可逆性（3.4），而期望在原则上可逆。平局时的默认应偏向不可逆的一侧——这与 2.4 的”缺乏阻力下降证据时默认推定为负债”是同一原则的应用。</p><p><strong>规则三：来源检验（适用于全部分项）。</strong> 若只对财政项设来源检验，就是用一个案例校准整个测量仪器——该规则不是从理论推出的，而是从苏联的石油美元反推的。外部资源的污染并不只作用于财政：</p><ul><li>对<strong>期望</strong>：侨汇、外援消费品、外部示范效应可暂时压制不满，<strong>伪装成期望未上升</strong>；</li><li>对<strong>方案空间</strong>：外来模式供给可虚增可选方案数，<strong>伪装成方案空间在扩大</strong>；</li><li>对<strong>固化度</strong>：外部资本进入可暂时增加该安排下的职位与资产，<strong>伪装成固化在加深</strong>（方向相反的污染）。</li></ul><p>因此规则三应推广为通用形式：</p><blockquote><p><strong>任一分项的改善，只有来自内生来源时才计入”等待”证据；来自外部注入的改善，该分项记为”弃权”，不参与多数决。</strong></p></blockquote><p>弃权的处理须记账清楚：弃权项既不判等待也不判负债，有效分项数相应减少，判定结果须记为”（有效项数）:（对立项数）”，不得把弃权项计入任何一侧。</p><p>按此规则，苏联案例中财政项因外部注入而弃权，有效阻力项为三项（固化度、期望、方案空间），三项均判负债，判定记为 <strong>3:0（财政项弃权）</strong>。记账须清楚：弃权项不计入任何一侧，不得写成”四项全部指向负债”。</p><h3 id="_2-3-判据在哪一层适用" tabindex="-1">2.3 判据在哪一层适用 <a class="header-anchor" href="#_2-3-判据在哪一层适用" aria-label="Permalink to &quot;2.3 判据在哪一层适用&quot;">​</a></h3><p><strong>阻力趋势在系统层与具体改革层可以方向相反</strong>，若不明确层级，同一案例会得出相反结论。</p><ul><li><strong>系统层</strong>：以整个政体或整个治理体系为单位，问”该系统的总体改革阻力在下降吗”。新加坡（7.1）属于系统层阻力下降。</li><li><strong>具体改革层</strong>：以单项改革为单位，问”这项具体的变更，其阻力在下降吗”。韩国金融自由化、台湾汇率改革的拖延都很严重——<strong>即使系统层指标在改善，具体改革层仍可能是负债</strong>。</li></ul><p><strong>规则</strong>：判据默认在<strong>具体改革层</strong>应用，因为改革总是具体的。系统层指标只作为<strong>背景条件</strong>——它决定拖延的”容错空间”，但不决定某项具体拖延的性质。</p><p>一个系统可以同时满足”总体在现代化”与”某项改革被拖成负债”。把它整体判定为”等待”，是用总体趋势掩盖具体失败——<strong>这正是案例 E 最容易犯的错误</strong>（见 6.E）。</p><h3 id="_2-4-真实等待与冒充形态" tabindex="-1">2.4 真实等待与冒充形态 <a class="header-anchor" href="#_2-4-真实等待与冒充形态" aria-label="Permalink to &quot;2.4 真实等待与冒充形态&quot;">​</a></h3><p>拖延在四种情形中具备真实的等待价值，但每一种都有对应的冒充形态，而区分它们正是判据最实用的输出。</p><p>等待技术成熟是真实的，其冒充形态是 T₁ 议程研究化——区别在于研究是否产出可证伪的方案，还是持续产出”需进一步研究”。等待财政空间是真实的，其冒充形态是 T₆ 时机论——区别在于是否明确说明”条件成熟”的可观测指标；若从不说明，即为冒充。等待信息充分是真实的，其冒充形态是 T₃ 问题降级——区别在于诊断是否收敛，还是不断被重新定义为执行问题。等待协调达成是真实的，其冒充形态是 T₅ 责任错位——区别在于协调机制是否在拖延期间被建立，还是责任持续往返。</p><p><strong>一句话</strong>：真实的等待改善某些可观测变量；冒充的等待只改善文件数量。</p><p><strong>对称性声明</strong>：本文不主张拖延总是坏。等待技术成熟、等待财政空间、等待国际条件——这些都是真实的、有效的拖延。本文的主张更窄：<strong>在缺乏”阻力下降”证据的情况下，拖延应被默认推定为负债</strong>，因为第四节列出的十种技术大多不产生等待价值，只产生时间。</p><h3 id="_2-5-一个竞争解释-为什么不是双曲贴现" tabindex="-1">2.5 一个竞争解释：为什么不是双曲贴现 <a class="header-anchor" href="#_2-5-一个竞争解释-为什么不是双曲贴现" aria-label="Permalink to &quot;2.5 一个竞争解释：为什么不是双曲贴现&quot;">​</a></h3><p>在论证”信息时滞”之前，必须先排除一个更简单的对手。</p><p>C 立即支付、B 延迟支付这一结构，最简单的解释是<strong>现时偏向（present bias）</strong>：Akerlof（1991）关于拖延的经典分析，以及 Laibson（1997）的双曲贴现框架，都用”决策者过度看重当下”解释拖延。<strong>如果这只是贴现问题，本文的整个信息机制就是多余的。</strong></p><p>坦白说，本文能给出的前两条回应，对老练的贴现理论家<strong>不构成有效反驳</strong>：</p><ol><li>一个直觉的反驳是”若纯为贴现则信息干预无效”。但危机恰恰把 B 的支付时点<strong>从延迟拉到当下</strong>——这正是双曲贴现理论预测会行动的时刻。<strong>该反驳因此不成立。</strong></li><li>另一个直觉的反驳是”贴现无法解释长期停滞＋突然启动”。但”幼稚拖延者”（naive procrastinator）的标准动态恰恰就是这个形状。<strong>同样不成立。</strong></li></ol><p><strong>真正能区分两者的只有第三条，且它自身受两重污染：</strong></p><ul><li><strong>任期与 τ 可能正相关</strong>：干部频繁调动 → 政策连续性差 → 信息上行慢。两个解释在此纠缠，无法用观察数据分开。</li><li><strong>“击鼓传花”外部性</strong>：任期将满的领导人把改革留给继任者（收益归他人、成本归自己），这会污染任期—拖延的关系，且方向可能是<strong>非单调</strong>的。</li></ul><p><strong>因此本文放弃用任期做识别，改用信息制度的外生变动：</strong></p><blockquote><p><strong>以统计独立化、审计改革、媒体放开等制度的</strong>外生变动<strong>作为 τ 的冲击源，观察</strong>同一决策群体<strong>在冲击前后的拖延时长变化。</strong></p></blockquote><p>这个设计的优势在于：它固定了决策者群体（因而固定了偏好与贴现率），只变动信息环境。<strong>偏好不变而行为改变，即可归因于信息。</strong> 这是本文识别策略的核心，与研究议程第 2 项合并执行。</p><p>因此本文的定位收窄为一句：</p><blockquote><p><strong>贴现提供了一个基准模型（任何跨期拖延都可能含有现时偏向成分）；本文在其之上加入信息约束，并主张：信息制度的外生变动会改变拖延时长，这一效应无法由贴现解释。</strong> 二者是嵌套关系，本文识别的是<strong>增量</strong>。</p></blockquote><h3 id="三、四项机制-分工而非并列" tabindex="-1">三、四项机制：分工而非并列 <a class="header-anchor" href="#三、四项机制-分工而非并列" aria-label="Permalink to &quot;三、四项机制：分工而非并列&quot;">​</a></h3><p>四条机制的<strong>博弈主体不同</strong>，因此不是四个平行的解释，而是四个在不同位置上发挥作用的机制。</p><p><strong>消耗战</strong>（3.2）的主体是精英集团，它解释谁先让步，在集团势均力敌、成本分担未定时主导，属中期机制。<strong>个体不确定性</strong>（3.3）的主体是大众与个体，它解释为何没有自下而上的改革压力，在改革改变相对位置时主导。<strong>政策反馈</strong>（3.4）的主体是时间本身，它解释阻力为何内生增长，全程作用且单调。<strong>信息时滞</strong>（3.1）的主体是决策者，它解释为何系统性错判时机。</p><p><strong>关键关系</strong>：信息时滞不是第四个平行机制，而是<strong>其他三者的共同放大项</strong>。消耗战、个体不确定性、政策反馈都会产生压力信号，但这些信号能否抵达决策者，取决于信息时滞。因此：<strong>τ 越大，前三项机制造成的拖延越长。</strong> 这就是本节的组织原则，也是本文与主篇的咬合点。</p><h3 id="_3-1-硬成本与软代价-两条曲线的时间错位" tabindex="-1">3.1 硬成本与软代价：两条曲线的时间错位 <a class="header-anchor" href="#_3-1-硬成本与软代价-两条曲线的时间错位" aria-label="Permalink to &quot;3.1 硬成本与软代价：两条曲线的时间错位&quot;">​</a></h3><p>先划清与既有文献的边界，避免重复发明。</p><p><strong>Wilson 关于管制政治的经典分析</strong>已指出：利益集中而成本分散的政策，会因受益方组织度高、受损方组织度低而被维持。本文借用”集中／分散”这一半，<strong>不把它算作自己的贡献</strong>。</p><p><strong>本文的增量在两个维度</strong>：<strong>时间</strong>（C 即时、B 延迟）与<strong>信号</strong>（C 可见、B 不可见）。Wilson 处理的是同一时点上的组织度差异，本文处理的是<strong>跨时点的可见性差异</strong>。</p><p><strong>先讲清一处量纲问题</strong>：C 是<strong>存量</strong>——实施改革时的一次性支付；B 是<strong>流量</strong>——每期因未改革而持续产生的损耗。两者量纲不同，严格地说只能在统一为现值后比较。</p><p><strong>本文不把这一比较形式化</strong>，理由有二。其一，形式化要成立，必须假定决策者不知道信息时滞 τ 的存在、因而不会对其作贝叶斯校正；而即便 τ 的精确值不可知，幕僚的警告、邻国的先例、既往事故的记忆都构成正的先验，”观测不到 B”不等于”以为 B 为零”。要使模型产出结论，就必须额外假定一个<strong>退化的先验</strong>——这个假定无法由本文的概念辩护，只能靠禁止决策者学习来维持。其二，若把成本项写成 C(t) = C₀ + γt（线性），就与 3.4 政策反馈所要求的阻力<strong>超线性</strong>增长相冲突；两处各取对自己方便的曲率，互不引用。一个需要靠”决策者不会学习”和”曲率随意设定”才能成立的模型，不如不要。</p><p>删除形式化之后，本节的主张以文字表述，且只保留三条可检验的预测：</p><blockquote><p><strong>预测一</strong>：在控制问题严重程度后，改革的启动时点系统性滞后于问题可被独立证据识别的时点，且滞后长度与该领域的信息上行时滞正相关。<br><strong>预测二</strong>：在信息受控的系统中，改革的触发更多由离散事件（事故、危机、外部冲击）驱动，而非由论证驱动——因为论证本身是软信号，而软信号不改变决策者的比较。<br><strong>预测三</strong>：若某领域建立了制度化的信息生产（独立统计、审计、媒体），则该领域的启动时点应系统性提前，<strong>即使问题严重程度不变</strong>。</p></blockquote><p>三条预测都不依赖”决策者非理性”，只依赖他信息不全；也都不需要指定 C 与 B 的函数形式。</p><p>预测二需要一处限定，否则说过头了。”论证说服不了人”这种说法在历史上站不住：思想解放一类讨论确实部分改变了决策环境。准确的表述是：</p><blockquote><p><strong>论证在常态下是软信号，但在两种条件下可以硬化：其一，论证被制度化——进入正式议程、形成</strong>含有可核查指标、责任主体与时限<strong>的文件、获得组织载体；其二，论证与某个已经硬化的事件耦合。</strong> 孤立的知识分子论证通常无效；制度化的论证可以生效。</p></blockquote><p>这里必须与第四节的 T₁、T₄ 划清界限：T₁（议程研究化）与 T₄（换词不换事）的可观测签名同样是”课题组、征求意见稿、文件更新”。区别在于文件的内容——<strong>是否包含可证伪的方案、可核查的指标与明确的责任主体</strong>。产生这类文件的不是伪装，产生”需进一步研究”的才是。</p><p>这一修正也把 3.1 与第九节的正向推论接上——制度化正是 B 硬化的非危机路径。</p><h3 id="_3-2-消耗战-一个必须本地化的转译" tabindex="-1">3.2 消耗战：一个必须本地化的转译 <a class="header-anchor" href="#_3-2-消耗战-一个必须本地化的转译" aria-label="Permalink to &quot;3.2 消耗战：一个必须本地化的转译&quot;">​</a></h3><p>Alesina 与 Drazen（1991）关于稳定化改革为何被推迟的研究，给出了这一机制的严格版本：<strong>当改革成本必须由两个或多个集团分担、而分担比例未定时，拖延本身是博弈均衡</strong>——每一方都在等对方先承受不住。</p><p>但直接移植到集权语境会水土不服：<strong>在高度集中的系统中，往往不存在两个势均力敌的集团在打消耗战。</strong> 因此必须做一次明确的转译：</p><blockquote><p><strong>在集权系统中，消耗战的双方不是”集团 A 与集团 B”，而是”决策者的短期政治安全”与”系统的长期治理绩效”。</strong> 决策者押注的是：问题会先被增长消化掉；系统押注的是：决策者的资源会先耗尽。</p></blockquote><p>须注意一处严格性损失：转译后”系统”不是策略主体，博弈退化为决策者对自然的赛跑，原模型的混合策略均衡与”先让步者付出代价”只剩<strong>类比意义</strong>。因此下文的三个推论应被读作<strong>由原模型启发的可检验假说</strong>，而非从均衡推出的定理（详见文末《本文的限定与已知弱点》）：</p><ol><li><strong>拖延不是失败，是策略。</strong> 每一方都理性地等待，因为先让步的一方承担确定的成本。</li><li><strong>拖延时长取决于资源禀赋，而非问题严重程度。</strong> 一个财政尚有腾挪空间、或拥有外部资源注入的系统可以拖很久，<strong>恰恰因为它还撑得住</strong>。这解释了为什么石油美元的流入延长了苏联的拖延（见第九节）。</li><li><strong>拖延期间总成本持续上升。</strong> 这是”制度债务”最严格的形式化基础。</li></ol><p>由此得到一个可检验的、反直觉的推论：<strong>财政耗尽不是改革的障碍被清除，而是消耗战的一方被迫投降。</strong> 因此改革启动时点应系统性<strong>滞后于</strong>财政指标恶化时点，而非滞后于问题严重度峰值。</p><h3 id="_3-3-个体不确定性-即使多数人受益-改革仍被阻止" tabindex="-1">3.3 个体不确定性：即使多数人受益，改革仍被阻止 <a class="header-anchor" href="#_3-3-个体不确定性-即使多数人受益-改革仍被阻止" aria-label="Permalink to &quot;3.3 个体不确定性：即使多数人受益，改革仍被阻止&quot;">​</a></h3><p>Fernandez 与 Rodrik（1991）处理另一层：即使改革在总体上有利于多数人，只要<strong>个体不知道自己是否属于受益者</strong>，现状偏好仍会占上风。</p><p>其机制是：改革改变分配结构，而每个人在改革前只知道自己的现状，不知道改革后的位置。若个体风险厌恶且收益分布不确定，<strong>期望收益为正的改革仍可能获得多数反对</strong>。</p><p>这对”等待共识”这一最常见的拖延理由给出了严厉检验：</p><blockquote><p><strong>如果共识指”多数人认识到改革对自己有利”，那么在分配性改革中，这种共识不会自发形成</strong>——因为认识到有利的前提是先知道自己的位置，而位置只有在改革之后才揭晓。</p></blockquote><p>因此”等条件成熟”“等共识形成”在分配性改革中是一句没有终点的话。</p><p><strong>但必须给一个限定</strong>：在技术性改革中（不涉及再分配、只涉及效率），受益者是普遍且可预期的，等待共识确实有效。区分点在于：<strong>改革是否改变相对位置。</strong> 改变 → 等待共识是拖延；不改变 → 等待共识是审慎。</p><h3 id="_3-4-政策反馈-时间是阻力的生产者" tabindex="-1">3.4 政策反馈：时间是阻力的生产者 <a class="header-anchor" href="#_3-4-政策反馈-时间是阻力的生产者" aria-label="Permalink to &quot;3.4 政策反馈：时间是阻力的生产者&quot;">​</a></h3><p>前三条解释拖延为何发生，这一条解释它为何加速。</p><p>这一节必须承认一个文献事实：<strong>“拖延生产阻力”是政策反馈与路径依赖的标准论点。</strong> Pierson（1994, 2000, 2004）关于政策创造自身拥护者的研究，甚至给出了实证版本——福利制度会生产出依赖它、并会为它辩护的群体；里根与撒切尔削减福利之所以困难，正因为福利制度在数十年间制造出了自己的选民。</p><p>本文在 Pierson 之上的增量只有一条：<strong>把反馈与时间不对称接起来</strong>。Pierson 说明政策会生产拥护者；本文补充——<strong>这些拥护者的可见度远高于受损者</strong>，因为拥护者是集中的、可指认的、会主动表达的（硬成本），而受损者是分散的、延迟的、沉默的（软代价）。因此政策反馈不只是产生阻力，而是<strong>产生不对称可见的阻力</strong>。</p><p>具体到一个制度安排运行十年之后，会形成五项：</p><ul><li><strong>职位</strong>：围绕该安排设立的机构与编制；</li><li><strong>资本</strong>：依赖该安排定价的资产（许可证、配额、土地性质）；</li><li><strong>知识</strong>：一整套专业技能与操作流程；</li><li><strong>关系</strong>：基于该安排的合作网络；</li><li><strong>预期</strong>：以该安排为前提做出的个人长期决策（购房、择业、迁移）。</li></ul><p>于是改革的对象从”一个规则”变成”一整套生活方式”，而这五项都会在改革临近时被动员起来反对改革。</p><p><strong>这五项清单与下文的学术归属须分开说明。</strong> 清单的理论来源是 Olson（1982）关于分布性联盟与既得利益网络如何随时间累积的分析；而”政策创造自身拥护者”“阻力随时间内生增长”这一正反馈命题，来自 Pierson（1994, 2000, 2004）的政策反馈与路径依赖研究。<strong>清单属 Olson，正反馈属 Pierson</strong>，本文借用两者，不主张其中任何一项是自己的发现。</p><p><strong>这就是正反馈：拖延制造阻力，阻力制造更多拖延。</strong> 它比”既得利益阻碍改革”更精确之处在于——它指出既得利益是<strong>时间的函数</strong>，不是一开始就存在的常量。因此<strong>拖延不是被阻力阻挡，拖延在生产阻力。</strong></p><h3 id="_3-4b-承诺问题-为什么连温和方案也会退出议程" tabindex="-1">3.4b 承诺问题：为什么连温和方案也会退出议程 <a class="header-anchor" href="#_3-4b-承诺问题-为什么连温和方案也会退出议程" aria-label="Permalink to &quot;3.4b 承诺问题：为什么连温和方案也会退出议程&quot;">​</a></h3><p>3.4 解释了阻力如何增长，但还有一个现象它解释不了：<strong>为什么温和方案本身会从议程中消失？</strong> 阻力增长只应使方案更难通过，不应使温和方案<strong>不再被提出</strong>。</p><p>这需要引入承诺问题（Acemoglu &amp; Robinson 2006）：<strong>既得利益者知道”第一步之后还有第二步”</strong>——今天让渡一个审批权，明天就可能被要求让渡第二个；今天的温和方案是明天激进方案的先例。因此他们会<strong>连第一步也抵抗</strong>。</p><p><strong>但本节的机制延伸目前零证据，且唯一被拿来对照的案例不支持它。</strong> 承诺问题预测精英会预防性地排除温和方案；而苏联 1965 年的温和方案恰恰<strong>进入了议程并被采纳</strong>，1968 年之后（一个外生冲击）才中止。这一时间线更符合”冲击后逆转”，而非”预防性排除”。因此承诺问题在本册中应被读作<strong>待检验假说</strong>，不配任何案例，其功能仅是提出一个可检验的预测：<strong>在承诺不可信的环境中，方案的温和性不构成被采纳的优势。</strong></p><p>这比”阻力阻碍改革”更进一步，且直接解释本文在第九节观察到的现象——苏联 1965 年柯西金改革在 1968 年后被事实上中止、1979 年的尝试被限制在纯效率层面、到 1985 年温和方案已不在议程内：</p><blockquote><p><strong>温和方案不是被否决的，是被预防性地排除的。</strong> 因为接受一个温和方案等于承认”这一领域需要改革”，而这个承认本身构成了下一步的先例。</p></blockquote><p>由此得到一个本文最实用的推论，它比阻力增长更能解释方案空间的收缩：</p><blockquote><p><strong>在承诺不可信的环境中，改革的”温和性”不构成可接受性的优势。</strong> 这解释了为什么渐进主义在实践中常常失效——并非渐进方案不好，而是<strong>缺乏约束后续步骤的机制时，让步会被解读为示弱</strong>。</p></blockquote><p>这也给出一个可检验的预测：<strong>存在可信的”到此为止”承诺机制时（如明确的阶段性立法、有终点的过渡安排、第三方担保），温和方案的通过率应显著上升。</strong> 这与 Dewatripont &amp; Roland（1992）关于渐进改革正当性的论证形成对话——该文论证渐进优于大爆炸，但其成立需要”阶段划分是可信的”这一前提；本文补充的是：<strong>在承诺不可信的条件下，这个前提不成立。</strong></p><h3 id="四、拖延的技术-一套有手艺的主动实践" tabindex="-1">四、拖延的技术：一套有手艺的主动实践 <a class="header-anchor" href="#四、拖延的技术-一套有手艺的主动实践" aria-label="Permalink to &quot;四、拖延的技术：一套有手艺的主动实践&quot;">​</a></h3><p>拖延很少表现为”什么都不做”——那太容易被识别、太容易被追责。它通常表现为<strong>一系列看起来在做事的动作</strong>：消耗时间、产生文件、留下痕迹，但不改变规则。</p><p>（本文把这一现象放在 Brunsson（1989）”组织的伪善”框架下理解：组织通过<strong>言说、决策、行动</strong>三者的分离来应对矛盾要求——宣布一项决策而不实施，正是维持多重压力平衡的标准方式。<strong>T₁–T₁₀ 的多数条目可视为这一分离在改革议题上的具体形态</strong>，本文的贡献在于给出可编码的签名，而非发明该机制本身。）</p><p>#技术机制：把什么转换成什么可观测签名T₁议程研究化把”是否做”转换成”怎么做”课题组、论证会、征求意见稿——但无决策时点T₂试点无限期把全国变更转换成局部实验，再让实验永久化试点超出原定评估期仍既不推广也不废止；试点区既得利益形成T₃问题降级把结构问题重定义为技术／执行／个案问题“落实有偏差”“个别地方”“配套不完善”T₄换词不换事把实质变更转换成术语更新表述更新，权责与流程不变T₅责任错位把决策推给无权限或无信息的层级“地方先行探索”与”待中央统一部署”互推T₆时机论把”不做”转换成”还没到时候”反复出现”条件尚不成熟”，从不说明成熟条件是什么T₇个案赎买把规则变更转换成对具体人的补偿矛盾在个案层面化解，同类问题持续再生产T₈人事化把制度问题转换成个人问题换人、问责、整顿作风——问题原样复现T₉危机征用用外部紧急状态冻结长期议程每逢重大事件，改革议程整体后移T₁₀程序性消耗让每一步都合规，整体不前进每个环节都完成，链条接不上；无人可问责### 4.1 T₂ 必须正面回应它的反方</p><p>T₂（试点无限期）有一个强大的反方文献，回避它会使本文的定性失去辩护过程。</p><p><strong>Sebastian Heilmann（韩博天）关于”分级制政策试验”的研究论证：试点是中国政策过程的适应能力来源</strong>，而非拖延形态——通过在地方试验、筛选、再推广，系统获得了在不确定条件下推进变革的能力。</p><p>本文的回应不是否定它，而是给出<strong>区分条件</strong>：</p><blockquote><p><strong>试点是适应能力还是拖延，取决于它是否有终止规则。</strong> 一个有明确评估时点、明确推广标准、明确废止条件的试点，是 information-generating device；一个无评估时点、无推广标准、无废止条件的试点，是 time-consuming device。</p></blockquote><p><strong>可操作的区分签名</strong>：试点文件中是否载明<strong>评估时点</strong>、<strong>推广的触发条件</strong>、<strong>废止的触发条件</strong>。三项皆无者，判为 T₂。这一判据与 Heilmann 的论述并不冲突——他描述的是有筛选机制的试验（”由点到面”），而 T₂ 指的是<strong>筛选机制本身被取消</strong>的那一部分。</p><p>这使本文与 Heilmann 形成的是<strong>互补而非对立</strong>：同一制度安排内部，一部分试点在产生信息，另一部分在消耗时间，二者需要分别编码。</p><h3 id="_4-2-为什么这些技术有效" tabindex="-1">4.2 为什么这些技术有效 <a class="header-anchor" href="#_4-2-为什么这些技术有效" aria-label="Permalink to &quot;4.2 为什么这些技术有效&quot;">​</a></h3><p>三个性质，合起来解释了拖延的稳定性：</p><p><strong>其一，单步正当性。</strong> 研究是审慎，试点是稳妥，降级是实事求是，换人是回应关切。<strong>没有任何一步需要被认定为错误</strong>，因此没有任何一步可以被追责。</p><p><strong>其二，不可逆的时间支出。</strong> 这些动作消耗的是单向资源——时间、注意力、议程位置。研究两年之后，问题并没有变简单，但可以用来研究它的时间变少了。</p><p><strong>其三，也是最关键的——它们污染了判断窗口所需的信号。</strong> T₁ 与 T₆ 会持续产出”正在处理”的硬信号（文件数、会议数、试点数），而这些信号恰恰<strong>替代了、并挤出了</strong>关于问题本身是否恶化的软信号。决策者看到的证据是”我们一直在做这件事”，而不是”这件事没做”。</p><p>这一点与主篇的”硬信号过剩、软信号枯竭”是同一机制在决策层的表现：<strong>技术治理让系统更擅长记录自己的动作，而不是记录自己动作的效果。</strong></p><h3 id="_4-3-检验必须分层" tabindex="-1">4.3 检验必须分层 <a class="header-anchor" href="#_4-3-检验必须分层" aria-label="Permalink to &quot;4.3 检验必须分层&quot;">​</a></h3><p>一个容易犯的检验错误是统一用”信息是否增加”衡量全部技术——这是错配，因为 <strong>T₃/T₄/T₅ 根本不声称产生信息</strong>。正确做法是<strong>按每种技术所声称的功能分层检验</strong>。</p><p>声称在产生信息的（T₁、T₂），就检验信息是否真的增加——签名是持续产出”需进一步观察”而观察条件从不改变。声称在等待时机的（T₆、T₇、T₉），就检验危机是被<strong>推迟</strong>还是被<strong>避免</strong>——签名是同类问题以相同形态复现。声称在改变表述的（T₃、T₄、T₈），就检验问题是否以新名称复现——签名是换词后指标无变化、换人后问题原样。声称在程序合规的（T₅、T₁₀），就检验链条是否闭合——签名是各环节均已完成而整体毫无进展。</p><p>规则很简单：<strong>用一项技术自己声称的标准去检验它。</strong> 用”信息增长”检验一个从不声称产生信息的技术，是稻草人。</p><p><strong>T₉ 与危机须划界</strong>：T₉（危机征用）把外部紧急状态列为拖延技术，而 8.2、8.3 把危机列为开窗动力。同一类事件，在第四节是拖延技术，在第八节是推动力，因此必须给出划界条件，不可只按需要取用。</p><p><strong>划界条件</strong>：看该事件是否<strong>硬化了被拖延的那个问题本身</strong>。若外部紧急状态转移了注意力与资源、而<strong>被拖延问题的代价仍然处于软信号状态</strong>，它是 T₉（拖延技术）；若该事件使被拖延问题的代价在短期内变为硬信号（按 8.3 的三项判据），它是危机（开窗动力）。判据落在”该问题的代价是否变硬”，不落在事件的类型或规模。</p><h3 id="五、技术性改良的天花板-一个更准确的边界" tabindex="-1">五、技术性改良的天花板：一个更准确的边界 <a class="header-anchor" href="#五、技术性改良的天花板-一个更准确的边界" aria-label="Permalink to &quot;五、技术性改良的天花板：一个更准确的边界&quot;">​</a></h3><p>一种常见的二分是”技术性改良能解决效率问题，不能解决分配与权力问题”。这个二分不够准确——<strong>在现实中，效率问题往往就是分配问题</strong>：简化审批流程表面是效率，实质是剥夺中间部门的审批租金。</p><p>更准确的边界是福利经济学意义上的：</p><blockquote><p><strong>技术性改良在不触动权力结构与重大利益分配的前提下，能完成帕累托改进式（无人受损）的效率提升；一旦改革进入卡尔多—希克斯区域（有人受损、需要补偿机制），技术性改良就立刻撞墙</strong>——因为它没有再分配的授权，也没有补偿的资源。</p></blockquote><p>而撞墙时的标准表现，正是<strong>把分配问题重新定义为执行问题</strong>（T₃）。因此技术性改良的命运有一个可预测的形状：</p><blockquote><p>初期效果显著（效率空间大）→ 中期边际收益递减（易改的改完了）→ 后期只能在”加强”“深化”“落实”上做文章（剩下的都是卡尔多—希克斯区域）→ <strong>最终出现一个诊断：执行不力。</strong></p></blockquote><p>最后一步是这套逻辑的终点，也是最需要警惕的一步：当所有技术性手段用尽而问题依旧，系统倾向于把原因归结为执行者不力——于是 T₈（人事化）被调用，而问题的结构性成因被再次遮蔽。</p><p>（这与主篇的语言污染是同一现象在政策语言中的版本——该篇论证：当公共话语奖励”正确的表达”而非”准确的表达”，人会失去命名自身处境的能力。此处同理：<strong>“执行不到位”这句诊断本身，就是一个阻止进一步追问的装置。</strong>）</p><h3 id="六、六类形态-按机制变量压缩" tabindex="-1">六、六类形态（按机制变量压缩） <a class="header-anchor" href="#六、六类形态-按机制变量压缩" aria-label="Permalink to &quot;六、六类形态（按机制变量压缩）&quot;">​</a></h3><p>以下六类不是政体分类，而是<strong>拖延的形态分类</strong>——同一政体可能先后落入不同形态。本节不复述历史，只提取与拖延机制直接相关的变量。案例 E 附完整重构。</p><h3 id="a-干部固化型-苏联-1964—1985" tabindex="-1">A. 干部固化型（苏联，1964—1985） <a class="header-anchor" href="#a-干部固化型-苏联-1964—1985" aria-label="Permalink to &quot;A. 干部固化型（苏联，1964—1985）&quot;">​</a></h3><p><strong>机制变量</strong>：拖延由<strong>组织自我保全</strong>驱动。干部轮换制弱化后，掌握改革权的人正是被改革对象，改革能力与改革动机同步消失。 <strong>关键变量</strong>：1970 年代石油美元<strong>掩盖</strong>了技术停滞——这是”阻力未下降但被外部资源暂时覆盖”的典型。 <strong>结果</strong>：1985 年可改空间压缩至只剩”全改”。 （完整编码见第九节。）</p><h3 id="b-期望超前型-沙俄-1861—1917" tabindex="-1">B. 期望超前型（沙俄，1861—1917） <a class="header-anchor" href="#b-期望超前型-沙俄-1861—1917" aria-label="Permalink to &quot;B. 期望超前型（沙俄，1861—1917）&quot;">​</a></h3><p><strong>机制变量</strong>：拖延由<strong>兑现速度落后于期望速度</strong>驱动。托克维尔命题：革命不在压迫最深时爆发，而在压迫开始减轻时爆发。 <strong>特殊之处</strong>：改革是加速器而非缓冲器——改得越多，期望抬得越快。1905 年开杜马、1906 年《根本法》收回实权，改革与镇压交替，两头落空。 （托克维尔效应的经验检验存在分歧；Davies 的 J 曲线是另一版本且检验结果不一，本文将其作为待检验命题而非既定事实。）</p><h3 id="c-器物—制度脱耦型-晚清洋务、奥斯曼坦齐马特" tabindex="-1">C. 器物—制度脱耦型（晚清洋务、奥斯曼坦齐马特） <a class="header-anchor" href="#c-器物—制度脱耦型-晚清洋务、奥斯曼坦齐马特" aria-label="Permalink to &quot;C. 器物—制度脱耦型（晚清洋务、奥斯曼坦齐马特）&quot;">​</a></h3><p><strong>机制变量</strong>：拖延由<strong>对制度变更的禁忌</strong>驱动（”中体西用”／”本质不可动摇”）。 <strong>关键变量</strong>：改良是真实的、可见的、且被大量投入的——正因如此，它最有说服力地<strong>挤出</strong>了真正的制度变更。 <strong>推论</strong>：无制度配套的现代化是给旧结构装新零件，整体强度反而更低（新零件放大旧结构应力）。</p><h3 id="d-举债买稳定型-1970-年代波兰、匈牙利" tabindex="-1">D. 举债买稳定型（1970 年代波兰、匈牙利） <a class="header-anchor" href="#d-举债买稳定型-1970-年代波兰、匈牙利" aria-label="Permalink to &quot;D. 举债买稳定型（1970 年代波兰、匈牙利）&quot;">​</a></h3><p><strong>机制变量</strong>：拖延由<strong>外部资源购买</strong>，因此<strong>还款日不由购买者设定</strong>。 <strong>关键变量</strong>：把政治问题转换成财务问题——利率、油价、信贷条件一变，交易立即破产。</p><h3 id="e-发展型且终局开放型-韩国、台湾、智利-——-附论证重构" tabindex="-1">E. 发展型且终局开放型（韩国、台湾、智利）—— 附论证重构 <a class="header-anchor" href="#e-发展型且终局开放型-韩国、台湾、智利-——-附论证重构" aria-label="Permalink to &quot;E. 发展型且终局开放型（韩国、台湾、智利）—— 附论证重构&quot;">​</a></h3><p><strong>一个必须规避的推理</strong>：用”最终完成转型”倒推”前半段是等待”。这是事后归因，正是本文判据要规避的那类推理。若韩国当时崩溃了，我们会把它归入负债类——<strong>而判据的价值恰恰在于它能在当时就判定，不依赖结局。</strong></p><p><strong>重构后的论证</strong>（只用 1980 年代可观测的当期指标）：固化度一项是混合的——财阀集中度虽高，但出口竞争使其持续面对外部规则约束，军政集团自身也有任期终点的预期；期望一项明确指向负债，教育扩张与城市化使期望快速上升；而财政与替代方案两项指向等待——高速增长提供了持续的腾挪空间，中产壮大与社会组织生长使温和方案的数量在增加。</p><p><strong>结论</strong>：按判据，韩国在<strong>系统层</strong>属等待（财政与方案空间改善），但在<strong>具体改革层</strong>（如金融自由化）属负债——金融压抑下的财阀—政府—银行三角阻力长期上升，直到 1997 年危机才被硬化处理。</p><p><strong>这正是 2.3 层级区分的价值</strong>：一个系统可以同时在系统层是等待、在具体层是负债。把它整体判为”等待”，就是用总体趋势掩盖具体失败。</p><p><strong>共同条件</strong>（仍是真实的，但不再用作推论依据）：出口导向的外部规则约束、土地改革与教育扩张带来的真实社会流动、外部参照系与安全保障者。</p><h3 id="f-封闭型-缅甸、津巴布韦、朝鲜" tabindex="-1">F. 封闭型（缅甸、津巴布韦、朝鲜） <a class="header-anchor" href="#f-封闭型-缅甸、津巴布韦、朝鲜" aria-label="Permalink to &quot;F. 封闭型（缅甸、津巴布韦、朝鲜）&quot;">​</a></h3><p><strong>机制变量</strong>：拖延由<strong>封闭本身</strong>驱动——无需兑现绩效，也无外部约束，拖延不需要理由。 <strong>特殊位置</strong>：它不是”拖延失败”，而是<strong>拖延成功</strong>（成功维持了现状），代价由全体居民承担。这与主篇的脆性判定一致：脆性决定断裂的方式，不决定断裂的必然性。</p><h3 id="归纳-拖延由什么驱动" tabindex="-1">归纳：拖延由什么驱动 <a class="header-anchor" href="#归纳-拖延由什么驱动" aria-label="Permalink to &quot;归纳：拖延由什么驱动&quot;">​</a></h3><p>六类形态可归为四种驱动源。<strong>组织自我保全</strong>（A、C）使阻力持续上升，判为负债；<strong>外部资源购买</strong>（D、F）使阻力被掩盖或变得无关，前者判为负债、后者只是停滞；<strong>真实收益抵消</strong>（E）给出混合信号，须分层判定——系统层是等待，具体层是负债；<strong>改革抬升期望</strong>（B）使阻力上升，判为负债，因为在这里改革是加速器而非缓冲器。</p><h3 id="七、对照组-为什么有的系统拖得起" tabindex="-1">七、对照组：为什么有的系统拖得起 <a class="header-anchor" href="#七、对照组-为什么有的系统拖得起" aria-label="Permalink to &quot;七、对照组：为什么有的系统拖得起&quot;">​</a></h3><p>只用 A–D 与 F 归纳，会犯一个典型错误：<strong>用已知崩溃的样本归纳崩溃的原因。</strong> 必须补入未崩溃的对照组，并处理抽样逻辑。</p><p>抽样上还有一个无法完全消除的深水区：正因为有些系统在危机前完成了改革，所以它们没有发生危机，我们的样本里看不到它们。这是选择效应。本文的处理是不声称估计效应量，并把研究单位下沉到具体改革——同一政体内有的改革被拖延、有的被及时实施，这个变异不受”政体是否崩溃”的选择影响。</p><h3 id="_7-1-新加坡-最大的反例-也是判据的正面案例" tabindex="-1">7.1 新加坡：最大的反例，也是判据的正面案例 <a class="header-anchor" href="#_7-1-新加坡-最大的反例-也是判据的正面案例" aria-label="Permalink to &quot;7.1 新加坡：最大的反例，也是判据的正面案例&quot;">​</a></h3><p>新加坡在政治结构上与主篇描述的脆性秩序高度相似——压制公共批评、<strong>大众回路脆化</strong>——却长期未崩溃，也未归入 E 类（未完成西式转型）。它是”绩效合法性必然到期”最直接的挑战。</p><p>仅以”阻力在下降”一句带过是不充分的。必须点出它的<strong>特殊信息机制</strong>：</p><blockquote><p><strong>新加坡证明：如果关上公共批评的门，就必须造一扇极其坚固的内部纠错的窗，否则必然负债。</strong></p></blockquote><p>三个具体机制：</p><ol><li><strong>精英回路的替代通道。</strong> 主篇指出，精英回路的失效机制是晋升与惩罚结构（传递坏消息的人承担风险）。新加坡的高薪、严格内部纪律与相对可预期的晋升规则，通常被解释为”切断寻租动机”（即主篇 2.3 补充的”说了会断财路”那一层）。</li></ol><p><strong>但这一解释的方向未定，本文必须承认两种相反的预测。</strong> 按主篇 M₁ 的成本结构，岗位价值越高，失去它的代价越大，<strong>避险型信息压制应当更强而非更弱</strong>；而按”高薪养廉”的解释，高薪降低寻租收益，应当削弱寻租型压制。两个机制预测相反，本文无材料裁决。要裁决它，需要比较不同薪酬水平下的内部坏消息上行率，或比较同类政体中薪酬与信息上行质量的相关性——本文两者皆无。<strong>因此本条只作为”存在替代通道”的候选解释列出，不作为已确立的机制。</strong></p><ol><li><strong>硬信号的制度化生产。</strong> 住房、公积金、就业、教育等领域存在高密度、可核实的量化指标，且这些指标的采集<strong>不经过被监督者的层级</strong>。</li><li><strong>真实存量的持续创造。</strong> 组屋与公积金不只是福利，它们把居民变成<strong>有存量可损失的人</strong>——这既提高了稳定性，也意味着系统必须持续兑现以避免存量受损引发的反应。</li></ol><p>按本文判据，新加坡是<strong>系统层阻力下降</strong>的正面案例：持续的绩效兑现、真实的存量创造、产业结构持续升级。<strong>它说明的不是”拖延无害”，而是”阻力可以真的下降”</strong>——只是这需要极高密度的持续兑现能力，因而不构成对本文命题的反驳，而构成对它的<strong>边界标定</strong>。</p><h3 id="_7-2-越南-一个需要修正的对照" tabindex="-1">7.2 越南：一个需要修正的对照 <a class="header-anchor" href="#_7-2-越南-一个需要修正的对照" aria-label="Permalink to &quot;7.2 越南：一个需要修正的对照&quot;">​</a></h3><p>一个值得修正的判断：越南常被归为”窗口内从容行动”，但 <strong>Đổi Mới（革新开放）恰恰是 1980 年代中期危机驱动的</strong>——通胀失控、计划经济失效、国际援助断裂。<strong>它不是”窗口内从容行动”的样本，而是”危机把 B 硬化后行动”的样本。</strong></p><p>这一修正对本文有利而非有害：它使越南从”反例”变成<strong>本文核心预测的一个支持案例</strong>（3.1：只有危机能把软信号硬化）。</p><h3 id="_7-3-政党型威权的耐用性" tabindex="-1">7.3 政党型威权的耐用性 <a class="header-anchor" href="#_7-3-政党型威权的耐用性" aria-label="Permalink to &quot;7.3 政党型威权的耐用性&quot;">​</a></h3><p>政体类型学的研究显示，以强政党为组织载体的威权形态显著比个人型与军人型更耐用，且更可能以<strong>非崩溃方式</strong>终结（Geddes 1999；Geddes, Wright &amp; Frantz 2014）。这直接相关，必须正面处理。</p><p><strong>为什么强政体会更耐拖？</strong> 因为它提供了一条<strong>替代性的信息通道</strong>。主篇指出，精英回路的失效机制是晋升与惩罚结构；而强政党在相当程度上能够绕开这一失效——通过组织纪律、内部调研与干部轮换，维持一条不依赖公开批评的上行通道。<strong>用主篇的变量说：强政党提高了精英回路的冗余度。</strong></p><p>由此得到本文必须承认的限定：</p><blockquote><p><strong>拖延是否致命，取决于政体的组织载体。</strong> 拥有独立信息通道与精英协调机制的系统，其”窗口”关闭得更慢，甚至可以通过上层重组完成调整，而不必等到危机。</p></blockquote><p>这削弱了本文结论的强度，但它是真实的，且把本篇接回主篇的核心变量——<strong>冗余度</strong>。两篇在此处合流：<strong>冗余度既决定脆性（主篇），也决定拖延的后果（本篇）。</strong></p><h3 id="_7-4-抽样逻辑" tabindex="-1">7.4 抽样逻辑 <a class="header-anchor" href="#_7-4-抽样逻辑" aria-label="Permalink to &quot;7.4 抽样逻辑&quot;">​</a></h3><p>即便补了对照组，仍有一个深水区问题：</p><blockquote><p><strong>正因为有些系统在危机前完成了改革，所以它们没有发生危机——于是我们的样本里看不到它们。</strong></p></blockquote><p>这是典型的选择效应，且在观察数据上无法完全消除。本文的处理是两条：</p><ol><li><strong>不声称估计效应量。</strong> 本文只主张机制的存在与方向，不主张”拖延导致崩溃”的概率。</li><li><strong>把研究单位下沉到具体改革而非政体。</strong> 政体层面的样本被选择效应污染（我们只看到崩溃的政体），但<strong>具体改革层面的样本不是</strong>——同一个政体内，有的改革被拖延、有的被及时实施，这个变异不受”政体是否崩溃”的选择影响。<strong>这是本文判据必须落在具体改革层的第二个理由</strong>（第一个理由见 2.3）。</li></ol><h3 id="八、窗口、危机与制度债务" tabindex="-1">八、窗口、危机与制度债务 <a class="header-anchor" href="#八、窗口、危机与制度债务" aria-label="Permalink to &quot;八、窗口、危机与制度债务&quot;">​</a></h3><h3 id="_8-1-窗口-放弃伪公式-改定性表述" tabindex="-1">8.1 窗口：放弃伪公式，改定性表述 <a class="header-anchor" href="#_8-1-窗口-放弃伪公式-改定性表述" aria-label="Permalink to &quot;8.1 窗口：放弃伪公式，改定性表述&quot;">​</a></h3><p>一种看似严谨实则伪精确的写法是 W(t) = 联盟规模 × 财政空间 × 外部约束 − 固化度。它的函数形式没有行为基础：为什么前三项是乘法、第四项是减法？而且——<strong>若外部约束为 0（封闭型），窗口就为 0 吗？</strong> 事实上封闭型系统可能自认为窗口很大（想改随时可改），也可能完全没有改革动力。<strong>外部约束是双刃剑</strong>：它既可能逼迫改革（提供动力，如关税与贸易规则），也可能冻结改革（战争与紧急状态）。把它作为单调乘数是不成立的。</p><p><strong>改为定性表述</strong>：</p><blockquote><p><strong>改革窗口是政治联盟、财政空间、以及”外部条件朝有利于改革的方向变化”三者的交集；既得利益固化度则是这个交集的侵蚀剂。</strong> 三个条件须同时具备（故为交集而非乘积），而固化度单向侵蚀、不可逆。<br> 第三项必须保留方向性：<strong>外部约束是双刃剑</strong>，它既可能逼迫改革（关税与贸易规则），也可能冻结改革（战争与紧急状态）。因此不能用”外部压力”这一同义词吸收方向问题，只把”朝有利于改革的方向变化”这一特定情形计入窗口。</p></blockquote><p>这个表述保留了全部实质内容，且消除了量纲与函数形式的伪精确。</p><p>由此得到一个反直觉推论：<strong>窗口最常见的闭合方式不是”机会没来”，而是”机会来过但错过了”。</strong> 因为前三项的恶化是可逆的（财政可恢复、联盟可重组、外部约束可重现），而固化度不可逆。</p><h3 id="_8-2-窗口是双向的-阻力是单向的" tabindex="-1">8.2 窗口是双向的，阻力是单向的 <a class="header-anchor" href="#_8-2-窗口是双向的-阻力是单向的" aria-label="Permalink to &quot;8.2 窗口是双向的，阻力是单向的&quot;">​</a></h3><p>一个常见的追问是：控制强度会不会只朝一个方向走？一旦开始管控，是不是只会越来越紧，窗口越来越小？</p><p><strong>直觉是对的，但表述必须改一个字：不是”只能单向移动”，而是”两个方向的机制不对称”。</strong> 一字之差，结论完全不同——前者是不可逆的宿命，后者是可检验的结构偏向。</p><p><strong>为什么它看起来像棘轮？因为收紧和放松不是同一种动作。</strong></p><p>本文主张收紧具有三条自动机制：其一，审查机构需要证明自身有用，因而倾向于不断扩展审查范围；其二，晋升竞争中的执行者倾向于”向上加码”，因为更严格总是更安全；其三，每一轮收紧都会制造一批依赖该安排获取职位与预算的人，他们成为下一轮收紧的推动者。</p><p><strong>必须声明：这三条是待检验的机制假说，不是已确立的组织学结论。</strong> 本文未为它们提供任何科层制文献支撑，下文的”重力／推力”只是对上述假说的形象说法，本身不构成论证。</p><p>放松则<strong>必须有人决断，且这个人要承担风险</strong>。这一点比上一段稳妥：它是从”放松缺乏自动机制”这一对称性观察推出的，而不是从关于动机的断言推出的。 观察到的”越来越紧”，是重力在起作用，不是因为反方向不存在。</p><p><strong>反方向确实存在，而且案例不少。</strong> 赫鲁晓夫的解冻、戈尔巴乔夫的公开性、蒋经国 1987 年解严、韩国 1987、佛朗哥之后的西班牙、越南的革新开放——窗口都曾显著打开过。（巴西 1974–85 的”逐步开放”不在此列，理由见下文：它是渐进放松，与本文的步长预测冲突。）</p><p><strong>最干净的一个案例是缅甸</strong>：2011–2015 年大幅开放，2012 年废除出版审查，Facebook 在数年内成为事实上的公共领域；2021 年政变，一夜之间全部收回。同一个国家，两个方向都完整走了一遍。<strong>这一个案例就足以否定”单向”命题。</strong></p><p>因此本文的准确表述是：</p><blockquote><p><strong>窗口双向移动，但阻力单向累积。</strong></p></blockquote><p>收紧期间建立起来的机构、编制、法规、惯例，以及靠它们吃饭的人，在放松时并不消失——它们只是暂时不被激活。<strong>每一次重新开窗，都要比上一次推得更用力。</strong></p><p>这不是新机制，而是本文已有机制收回自身：主篇第十节的棘轮（在结构不变时是棘轮式的，结构剧变作为外生冲击可重置它）、本篇 3.4 的政策反馈（拖延生产阻力，控制机构会生产出自己的拥护者）、以及危机作为外生冲击对棘轮的重置——三者是同一个机制的不同面，同样适用于”控制强度”这个变量本身。</p><p>由此得到两条预测，但两条都必须先修掉自身的缺陷。</p><p>其一，<strong>两个方向的形态应当不同</strong>：收紧应是<strong>频繁而小幅</strong>的，放松应是<strong>稀少而大幅</strong>的。但巴西 1974–85 恰好违反这条——它的开放以”缓慢、渐进、安全”为官方纲领，是连续渐进放松的教科书案例，因此不在支持名单之列。据此，放松的形态可能是<strong>双峰</strong>的：一类由离散事件驱动的一次性大幅开放，一类是技术官僚主导的渐进开放。本预测只覆盖前者：<strong>大幅放松应由离散事件驱动</strong>；至于渐进放松，本文没有预测，也不把它算作支持证据。</p><p>其二，<strong>放松应由离散事件驱动，而非连续漂移</strong>。但这里有一个机械性混淆必须排除：控制强度是有界变量（下界为零），<strong>有界变量的两个方向步长分布本就系统性不对称</strong>——接近下界时放松空间天然受限。因此该预测只在<strong>远离边界的区间</strong>内有意义，且必须与控制强度本身的测量指数一并定义，而本文目前没有定义这个指数。</p><p><strong>缅甸案例须承认两读。</strong> 2011–2015 的开放与 2021 的收回，既可以读作”双向”（本文的读法），也可以同等干净地读作”放松全可逆、建制不可逆”（棘轮的读法）。同案两读，本文无从裁决。要裁决它，需要比较 2011 年与 2021 年之后重新开放的<strong>门槛</strong>——若后者显著更高，则阻力单向累积成立；若门槛相当，则本文的”双向”主张只是观察到了一次可逆的摆动。</p><p><strong>最后要补一条上限，但这个上限很松。</strong> 主篇的绩效悖论给出了理论上限：控制信息会损害系统自身赖以维持绩效的信息，因此极端收紧会自我削弱，不会单调上升到无穷。但须诚实说明——这条反馈的时滞极长，且是”绩效受损”型而非”政权受损”型。实践中可能收紧很久、绩效明显下滑之后才触到它。<strong>这个上限在理论上存在，在经验上可能远得没有约束力。</strong></p><h3 id="_8-3-危机-必须界定-且必须承认它的代价" tabindex="-1">8.3 危机：必须界定，且必须承认它的代价 <a class="header-anchor" href="#_8-3-危机-必须界定-且必须承认它的代价" aria-label="Permalink to &quot;8.3 危机：必须界定，且必须承认它的代价&quot;">​</a></h3><p>“危机触发改革”这一命题若不加界定便不可靠：定义宽则不可证伪（任何压力都算），窄则反例成群（台湾 1980 年代末、韩国 1987 年的转型都不是经典意义上的危机触发）。</p><p><strong>界定必须首先满足一个条件：危机的判据不能包含”其后是否发生改革”，否则核心预测就成了重言式。</strong> 若把危机定义为”迫使系统在公开层面承认问题存在的离散事件”，而 3.1 的预测是”改革几乎总在危机之后发生”，则承认先于改革、危机又被定义为迫使承认的事件——预测由此被定义保证：凡改革的，其前置事件自动算作危机；凡无危机而改革的，又可归入”技术性改革”豁免。</p><p><strong>因此界定如下</strong>：危机 = 一个<strong>离散的、可独立观测的、且其发生不以其后是否改革为转移</strong>的事件，它使某领域未处理问题的代价在极短时间内从软信号变为硬信号。三项操作判据：</p><ol><li><strong>可独立观测</strong>：有公开可查的时间点、地点与规模（事故死亡人数、违约事件、统计异常、外部冲击的生效日）；</li><li><strong>离散</strong>：在时序上可定位到一个事件或一段明确区间，而非渐进趋势；</li><li><strong>与改革正交</strong>：该事件的编码不使用改革是否发生、何时发生的信息。</li></ol><p>按此界定，韩 1987、台 1987 的转型由大规模动员与戒严令失效等离散事件触发——它们是危机，只是烈度低于革命。同时须收窄豁免条款：<strong>“技术性改革无需危机”不能作为万能豁免口</strong>，否则任何反例都可被归入豁免。豁免只适用于<strong>不改变相对位置、不涉及分配冲突</strong>的改革（Dewatripont–Roland 意义上的纯协调问题），且须在编码时预先声明，不得事后归类。</p><p>即便如此，本文仍须承认：3.1 预测二的可检验性由此被削弱了一档——它现在检验的是”改革启动时点是否系统性滞后于可独立观测的危机事件”，而非一个由定义保证的关系。</p><p><strong>但必须补上常被忽略的那一半：危机触发的改革，其质量未必更高。</strong></p><p>这是一条对称的权衡，不写出来会使本文变成”危机万能论”：</p><blockquote><p><strong>危机中 B 被恐慌放大，仓促设计的改革可能比继续拖延更糟。</strong> 危机同时做两件事：它消除了信息时滞（好），也压缩了设计时间（坏）。</p></blockquote><p>更精确地说，危机不只消除时滞，还<strong>扭曲代价的权重结构</strong>——它迫使决策者优先处理短期生存威胁，从而<strong>挤出</strong>长期制度设计的空间。因此危机中的改革存在一个系统性的偏向：<strong>过度回应最紧迫的问题，而忽略最根本的问题。</strong></p><p>戈尔巴乔夫的改革是这一权衡的候选案例，但须避免单数归因——至少有两种竞争解释：其一是<strong>时间不足</strong>（危机硬化了 B，但没有留给渐进设计的时间，于是从”拖延”直接跳到”全改”）；其二是<strong>顺序错误</strong>（先政治后经济，导致经济改革失去执行能力）。本文不在这两者间做断定，只指出<strong>两者都指向同一个结论</strong>：危机触发的改革质量不因触发而来，而取决于危机前是否已备有可执行的方案。</p><p>由此得到第八节最重要的一条正向推论，也是本文最实用的一条政策含义：</p><blockquote><p><strong>如果 B 只能靠危机硬化，那么改革的代价必然包含危机的代价。</strong> 因此，<strong>能否在不发生危机的条件下硬化 B，决定了一个系统能否以低成本改革。</strong></p></blockquote><h3 id="_8-4-两类拖延-一个必须收编的反例" tabindex="-1">8.4 两类拖延：一个必须收编的反例 <a class="header-anchor" href="#_8-4-两类拖延-一个必须收编的反例" aria-label="Permalink to &quot;8.4 两类拖延：一个必须收编的反例&quot;">​</a></h3><p>B 的硬化不必靠危机，还可以靠<strong>制度化的信息生产</strong>：独立统计、审计、专业媒体、可核查的公开数据、独立司法的事实认定。由此可得一条正向推论——<strong>信息制度是危机的低成本替代</strong>。</p><p>但这里必须停住，因为一个更强的命题是错的，而且反例就在本文自己倚重的文献里。</p><p><strong>被证伪的全称命题</strong>：若断言”只要信息机构独立，B 就会被硬化，拖延就无法维持”，则 Alesina–Drazen 的<strong>原始经验域</strong>当场构成反例——拉美十余国的稳定化拖延、土耳其、印度，都发生在有独立统计与公开辩论的环境中；美国社会保障的精算缺口四十年来持续公开发布，法国退休改革的账本全民可查，日本农协保护的代价被独立媒体反复计算。<strong>这些系统里 B 早已硬化到”人人都知道欠多少”，拖延照样维持数十年。</strong> 必要条件为假。</p><p>更麻烦的是，这个全称命题与本文自己的分工表冲突：第三节把信息时滞定位为<strong>其他三者的放大器</strong>而非独立机制，这在逻辑上允许”τ 小但消耗战强”的拖延存在；而全称断言等于说”τ 小则拖延无法维持”。两处不能同时成立。</p><p><strong>正确的处理是把它限定，并由此得到更好的东西。</strong></p><p><strong>由此得到两类拖延的区分。</strong> 显性拖延的账本是可信的，问题清单公开可核；拖延之所以维持，不是因为不知道，而是因为<strong>分配未决——谁付代价还没谈拢</strong>，其维持机制是消耗战与否决结构。隐性拖延的账本本身是失真的，记账系统被污染；其维持机制是<strong>信息时滞</strong>——决策者不知道欠多少。</p><p>两者中危机的功能也完全不同：在显性拖延中，危机是一个<strong>政治窗口</strong>——承认早已完成，缺的只是行动授权；在隐性拖延中，危机是一个<strong>认知窗口</strong>——连”承认”都才刚刚开始。前者的典型是拉美稳定化、美国社保、法国退休、日本农协；后者是信息受控的系统。</p><p>由此得到一条可检验预测——显性债务系统在危机前应有持续的止损谈判记录（债务上限博弈、财政规则谈判、IMF 条款），隐性系统没有。</p><p>在此限定之下，原先那句反向推论才成立，且更有力：</p><blockquote><p><strong>控制独立统计、审计与媒体，不是一切拖延的必要条件，而是”隐性债务”得以维持的必要条件。</strong> 在一个账本本可独立的系统里，使其失真，正是为了让 B 保持在软信号状态。</p></blockquote><p>这一推论把主篇的言论命题与本篇的时机命题焊接成完整的因果链：<strong>压制公共批评不只是压制表达，它是把”显性拖延”降级为”隐性拖延”的操作。</strong> 它也让”为何要控制统计与媒体”这个问题有了一个非道德主义的回答——不是因为统治者的偏执，而是因为<strong>隐性化在结构上需要它</strong>。</p><p>（可检验预测见研究议程第 5 项；该设计须同时检验”止损谈判记录”这一差异，而非只检验启动时点。）</p><h3 id="_8-5-制度债务-显性还是隐性" tabindex="-1">8.5 制度债务：显性还是隐性 <a class="header-anchor" href="#_8-5-制度债务-显性还是隐性" aria-label="Permalink to &quot;8.5 制度债务：显性还是隐性&quot;">​</a></h3><p>经济债务有本金、利率与到期日，制度债务没有——这使它更危险，也使”债务”一词容易沦为比喻。因此需要区分：</p><ul><li><strong>显性制度债务</strong>：知道欠多少（问题清单清楚）、知道利率（拖延的年度成本可估）、有到期压力。<strong>可被管理。</strong></li><li><strong>隐性制度债务</strong>：不知道欠多少，且<strong>记账系统本身被污染了</strong>（主篇的绩效悖论：为维护绩效叙事而压低失败可见度）。<strong>不可被管理。</strong></li></ul><p><strong>关键判断</strong>：脆性系统的真正问题不是欠债多，而是它的记账系统被自己的信息机制污染了——<strong>它记的是自己的动作（文件数、会议数、试点数），而不是自己动作的效果。</strong></p><p>这解释了为什么同样的债务水平在不同系统中后果差异极大：有的系统知道自己欠多少，因而能在临界点前处置；有的系统在崩溃前一天仍在报告”稳中向好”。<strong>差别不在债务规模，而在记账的可信度。</strong></p><p>这里有一处需要调和的张力：本文既说”显性债务可管理”，又说”缺乏阻力下降证据时应默认推定为负债”。调和后的表述是：<strong>显性化是拖延从”负债”回转”等待”的唯一通道</strong>——知道自己欠多少，就有可能在窗口内处置。这与 8.4 是同一件事：信息独立既硬化 B，也使债务显性。但须注意，8.4 已证明显性化<strong>只是必要条件</strong>：账本可信的系统照样拖延，因为分配冲突未决。</p><h3 id="_8-6-迟滞-本篇与主篇的共同项" tabindex="-1">8.6 迟滞：本篇与主篇的共同项 <a class="header-anchor" href="#_8-6-迟滞-本篇与主篇的共同项" aria-label="Permalink to &quot;8.6 迟滞：本篇与主篇的共同项&quot;">​</a></h3><p><strong>问题层面的迟滞</strong>：约束解除后，问题不沿原路返回。即使改革决定终于做出，实施成本仍高于当初估计——因为组织已完成适应性变形（3.4 的五项）。<strong>改革面对的不再是最初那个问题，而是那个问题长成的新形态。</strong></p><p><strong>人格层面的迟滞</strong>（主篇 M₄ 与 M₈）：约束解除后，人的能力不沿原路返回。该篇 M₄ 论证：公民技能是需要持续排练才能维持的情感与表达实践，其萎缩可逆但恢复需时；M₈ 论证：这种习得会经家庭社会化传给下一代，使第二代人缺少”失去感”，恢复更慢。</p><p>两者叠加，产生本篇最后一个、也是最悲观的推论：</p><blockquote><p><strong>长期拖延之后，即使做出正确的改革决定，系统也可能已经失去了执行它的人。</strong></p></blockquote><p>主篇解释”人为什么不会了”，本篇解释”为什么到人不会的时候才决定要会”。<strong>这两件事发生在同一个时间轴上，这不是巧合——它们是同一个信息失灵的两面。</strong></p><h3 id="九、演示-苏联-1964–1985-的编码过程" tabindex="-1">九、演示：苏联 1964–1985 的编码过程 <a class="header-anchor" href="#九、演示-苏联-1964–1985-的编码过程" aria-label="Permalink to &quot;九、演示：苏联 1964–1985 的编码过程&quot;">​</a></h3><p>判据若从未被执行，就只是又一层修辞。本节完整演示一次编码过程。</p><p>本节展示的是<strong>编码的规程</strong>——测什么、用什么数据源、方向如何判定——以及各项的<strong>方向判断</strong>，逐项详表见附录二。此处不使用未经核实的数字作为论据；但”不用未核实数字”不应被用作连<strong>已核实数值</strong>也一并推迟的理由：政治局与中央委员的平均年龄、连任率、外债与谷物进口规模在二手文献中已有确立数值，正式版本应填入并标注出处。</p><h3 id="_9-1-改革对象的界定-层级-具体改革层" tabindex="-1">9.1 改革对象的界定（层级：具体改革层） <a class="header-anchor" href="#_9-1-改革对象的界定-层级-具体改革层" aria-label="Permalink to &quot;9.1 改革对象的界定（层级：具体改革层）&quot;">​</a></h3><p>按 2.3 规则，判据须落在具体改革上。本文选取：**“从指令性计划向有限的市场协调过渡”**这一具体变更（其历史形态为 1965 年柯西金改革 → 1970 年代停滞 → 1979 年有限尝试 → 1985 年后全改）。</p><h3 id="_9-2-编码过程-数据源与逐项编码表见附录二" tabindex="-1">9.2 编码过程（数据源与逐项编码表见附录二） <a class="header-anchor" href="#_9-2-编码过程-数据源与逐项编码表见附录二" aria-label="Permalink to &quot;9.2 编码过程（数据源与逐项编码表见附录二）&quot;">​</a></h3><p><strong>固化度</strong>持续上升，指向负债：”稳定干部队伍”成为组织原则、轮换制弱化，到后期赫鲁晓夫时期的轮换被系统性逆转，老龄化加剧。<strong>期望</strong>加速上升，也指向负债：官方承诺的调门持续抬高而交付滞后，落差在整个时期扩大。<strong>财政</strong>是唯一反向的一项——石油冲击带来的外汇使其在 1970 年代表面改善，随后军费、阿富汗战争、谷物进口依赖、对经互会成员的补贴义务使其急剧恶化。<strong>方案空间</strong>持续收缩，也指向负债：1965 年柯西金改革在 1968 年后被事实上中止，1979 年的尝试局限于效率层面，到 1985 年温和方案已不在议程内。</p><p><strong>五处编码纪律的说明（这正是演示的价值所在）</strong>：</p><p>其一，<strong>期望项的代理必须唯一。</strong> 用排队时长、住房等待年限测”期望”是错的——这些是<strong>短缺</strong>指标，且存在致命的双向解读：长期排队既可编码为”期望未满足”，也可编码为”期望已被调适、人已适应”（这恰是主篇 M₄＋M₈ 预测的方向）。代理不唯一，编码就不可靠。本文改用**“官方承诺—实际兑现的落差”**：期望主要被官方话语抬升（6.B 的机制），测量应落在话语与兑现的落差上。</p><p>其二，<strong>时间线不得溢出编码窗口。</strong> 财政在 1975–1985 段的证据须落在该窗口内——军费攀升、1979 年后的阿富汗战争、谷物进口依赖、1980 年后对波兰等国的补贴义务在窗口内；”1986 年油价暴跌”在窗口外，不得用作该段依据。</p><p>其三，<strong>本节的编码须遵守主篇的核心经验命题。</strong> 主篇第五节指出：在信息受控的系统中，官方统计被奖励机制系统性塑形，因而<strong>不可作为证据使用</strong>。若本节的”实际兑现”一方取苏联官方的计划完成率与消费品供给统计，就等于用被判定为不可信的来源充当证据。<strong>“实际交付”因此必须使用独立证据源</strong>（如 CIA 对苏联国民经济的独立估计、实物产量与消费的第三方核算、排队与短缺的独立观察、后续解密档案），并与官方统计的<strong>偏离度</strong>一起记录。在获得此类独立源之前，期望分项的编码标记为<strong>低置信度</strong>，且不得单独承重。</p><p>其四，<strong>期望分项的理论方向未定，本文在此记录其编码理由。</strong> 期望上升在威权语境下既可能降低改革阻力（社会压力增大迫使让步），也可能提高精英阻力（恐惧开启不可控进程）。方向取决于<strong>改革决策权落在哪一层</strong>。苏联案例中决策权在精英层，因此期望上升记为<strong>阻力上升（负债向）</strong>。这不是从理论推出的，是对具体权力结构的判断，须在编码手册中逐案声明。</p><p>其五，<strong>财政分项不属于”阻力”</strong>，它是调节变量，不参与多数决。</p><h3 id="_9-3-判据结论与一个关键的中间发现" tabindex="-1">9.3 判据结论与一个关键的中间发现 <a class="header-anchor" href="#_9-3-判据结论与一个关键的中间发现" aria-label="Permalink to &quot;9.3 判据结论与一个关键的中间发现&quot;">​</a></h3><p><strong>结论</strong>：三分项阻力中，<strong>固化度、期望、方案空间在整个拖延期内单调恶化</strong>；财政（调节变量）在 1970 年代因石油租金改善，1980 年代急剧恶化。</p><p>按此规则，财政项因外部注入而弃权，有效阻力项为三项，三项均判负债，判定记为 <strong>3:0（财政项弃权）</strong>。因此苏联 1964–1985 属于<strong>负债</strong>。</p><p>需注意，本节不主张”在 1975 年之前就已可判定”这类断代结论：各分项的”↑”“↓”是方向判断，不是时间序列上的估值，本节的编码没有任何带日期的数据支撑。要主张某个具体年份已可判定，须给出该年份各分项的测量值或至少可比的分段数据。可主张的只是：按本节的编码规程，该拖延在整个窗口内持续判为负债，且其负债性质不依赖 1991 年的结局即可判定。</p><p><strong>一个关键的中间发现</strong>：</p><blockquote><p>财政的改善（石油美元）不但没有降低阻力，反而<strong>延长了拖延</strong>，且<strong>加剧了最终的负债</strong>。</p></blockquote><p>机制是清楚的：外汇流入提高了消耗战中的资源禀赋（3.2 推论 2：拖延时长取决于资源禀赋而非问题严重程度），从而使系统可以继续等待；而在等待期间，固化度与期望继续累积。<strong>外部资源的注入把”负债”伪装成了”等待”，直到资源消失，全部累积一次性显形。</strong></p><p>这给出一个可迁移的推论，且可在其他案例上检验：</p><blockquote><p><strong>外部资源的临时性注入（资源租金、外债、援助）会系统性地延长拖延，并放大最终的调整成本。</strong> 它是最危险的”等待伪装”。</p></blockquote><p>这与 D 类（举债买稳定型）的机制完全一致——<strong>苏联 1970 年代与波兰 1970 年代是同一个机制的两个版本</strong>，区别只在于苏联的资源是租金而波兰的是信贷。<strong>这也说明六类形态不是互斥的分类，而是可叠加的机制。</strong></p><p><strong>这个发现应当反哺判据本身</strong>，这是本节最重要的产出——见 2.2b 规则三：</p><blockquote><p><strong>财政分项的改善须做来源检验：内生改善计入”等待”证据，外部注入（租金、信贷、援助）不计入。</strong></p></blockquote><p>按推广后的规则重新计算，苏联案例中财政项由”计入等待”改为”弃权”，判定为 <strong>3:0（财政项弃权）</strong>——有效阻力项全部指向负债，无例外项需要额外解释。记账须清楚：弃权项不计入任何一侧。</p><h3 id="_9-4-演示的方法论要点" tabindex="-1">9.4 演示的方法论要点 <a class="header-anchor" href="#_9-4-演示的方法论要点" aria-label="Permalink to &quot;9.4 演示的方法论要点&quot;">​</a></h3><ol><li><strong>三分项阻力均可在改革尚未发生时测量</strong>，因此不构成事后归因。</li><li><strong>分项之间可以不同向</strong>。若用一个总体印象（”苏联很僵化”）代替分项编码，就会漏掉”财政曾改善”这一关键事实，从而漏掉 9.3 的发现。</li><li><strong>编码单位是具体改革</strong>（2.3），不是”苏联这个政体”。</li><li><strong>代理必须方向唯一，且不得溢出时间窗口</strong>。</li><li><strong>本章全部编码为方向判断与规程演示，无一处填入测量值</strong>。在获得独立证据源之前，本册不声称对苏联案例作出了任何量化编码。</li></ol><h3 id="十、研究议程" tabindex="-1">十、研究议程 <a class="header-anchor" href="#十、研究议程" aria-label="Permalink to &quot;十、研究议程&quot;">​</a></h3><ol><li><strong>拖延事件数据库。</strong> 编码：问题首次识别时间、首次决策尝试、每次”非变更应对”的类型（对应 T₁–T₁₀）、拖延期间三分项阻力的变化、以及财政这一调节变量的走势，最后是最终处理方式。三条纪律：<strong>第一，记录”非变更应对”的类型</strong>——现有研究多只记录”未改革”，把拖延当作空白，而本文主张它是有内容的实践；<strong>第二，所有阻力指标使用改革启动前的同期数据</strong>，禁用事后回溯评价；<strong>第三，按 2.2b 的聚合规则判定</strong>（多数决、平局判负债、来源检验）。</li><li><strong>信息时滞 vs 贴现的区分检验（本文识别策略的核心）。</strong> <strong>不使用任期变量</strong>（2.5 已说明其受两重污染），改用<strong>信息制度的外生变动</strong>作为 τ 的冲击源：统计独立化、审计改革、媒体放开、信息公开立法的前后对比，观察<strong>同一决策群体</strong>的拖延时长变化。设计要点是固定决策者群体（从而固定偏好与贴现率），只变动信息环境——<strong>偏好不变而行为改变，即可归因于信息。</strong> 可行的自然实验包括：审计机构隶属关系变更、统计部门垂直管理改革、信息公开条例的实施前后。</li><li><strong>消耗战的财政测度。</strong> 检验：财政指标恶化时点是否系统性<strong>先于</strong>改革启动时点（3.2 的推论），而非问题严重度峰值先于启动时点。二者预测不同的时序。</li><li><strong>外部资源注入的伪装效应。</strong> 检验 9.3 的推论：资源租金、外债、援助的临时性流入，是否系统性延长拖延并放大最终调整成本。可用跨国面板：资源型经济体 vs 非资源型经济体的改革启动时点分布。</li><li><strong>两类拖延的差异化检验</strong>（8.4 的分类）。不宜只检验”信息独立性→启动时点更早”这一单向预测——8.4 已证明显性化不是充分条件。正确设计是<strong>检验三类差异</strong>：<strong>第一</strong>，危机前是否存在持续的止损谈判记录（债务上限博弈、财政规则谈判、IMF 条款）；<strong>第二</strong>，危机中改革方案的<strong>设计时间</strong>是否显著更短（显性系统应更长，因为认知早已完成）；<strong>第三</strong>，危机后改革的<strong>方向</strong>是否偏向短期生存（8.3 的权重扭曲预测）。<strong>预测：显性债务系统在第一、第二项上得分更高，在第三项上得分更低。</strong></li><li><strong>技术性改良的边际递减。</strong> 以某领域的政策文件数量与频率作为投入，以该领域可观测结果作为产出，检验边际产出是否为负——若是，则第五节的”天花板”命题成立。</li><li><strong>窗口双向性的步长分布检验</strong>（8.2）。以某领域控制强度的时序变化为数据，检验两个方向的<strong>步长分布</strong>：收紧应为高频小幅，放松应为低频大幅。同时检验放松是否由离散事件（领导层更替、危机、外部冲击、技术变化）驱动——若存在无触发事件的渐进放松，则本文的”机制不对称”命题需修正。这是本节唯一可以直接用公开文件序列完成的设计。</li></ol><h3 id="附录一-核心变量与可观测代理" tabindex="-1">附录一：核心变量与可观测代理 <a class="header-anchor" href="#附录一-核心变量与可观测代理" aria-label="Permalink to &quot;附录一：核心变量与可观测代理&quot;">​</a></h3><p>概念定义可观测代理改革拖延已知＋有能力＋提高了未来成本首次识别时点；非变更应对的类型与次数；三分项阻力与财政调节变量的变化决策者理性／社会理性信息集内最优／全信息最优二者的分离即拖延的悖论所在硬成本 C(t)集中、即时、可见的改革成本明确受损集团的数量与组织度；反对表态强度软代价 B(t)分散、延迟、不可见的拖延代价分散损失的累积估计；独立证据源与上报数据的偏离度信息时滞 τ问题恶化到进入决策视野的时间内部报告—公开披露时距；问题在统计中的显形延迟编码分项三分项阻力（固化度・期望・方案空间）＋财政调节变量见 9.2 的数据源列窗口联盟・财政・外部压力的交集，被固化度侵蚀三项是否同时具备；固化度的不可逆变化危机使 B 在短期内硬化的离散事件是否迫使系统公开承认问题存在显性／隐性制度债务记账系统是否可信是否存在独立证据源；问题清单是否公开可核迟滞约束解除后问题不沿原路返回决定做出后的实施成本 vs 当初估计；组织变形程度### 附录二：苏联 1964–1985 编码详表（第九节的技术细节）</p><blockquote><p><strong>本表为方向判断与数据源清单，不含测量值。</strong> 财政为调节变量，不参与多数决；期望项在获得独立证据源之前标记低置信度。</p></blockquote><p>分项可用数据源1965–1975 方向1975–1985 方向判定既得利益固化度苏共中央委员连任率；部长与州委第一书记平均任期；nomenklatura 规模；与该安排绑定的部门数与编制数↑ 明显（”稳定干部队伍”成为组织原则，轮换制弱化）↑ 继续（老龄化加剧，赫鲁晓夫时期的轮换被系统性逆转）持续上升 → 负债期望上升（低置信度）官方承诺—实际兑现的落差。“实际交付”须取独立证据源（CIA 独立估计、第三方实物核算、短缺的独立观察、解密档案），不得取苏联官方统计↑（承诺调门持续抬高，交付滞后）↑↑（交付停滞而承诺不降；落差扩大）加速上升 → 负债（方向须逐案声明，见 9.2 其四）财政（调节变量，不参与多数决）军费占 GNP 比重；谷物进口依赖度与进口量；硬通货外债规模；对经互会成员的补贴义务↑ 表面改善（1973、1979 两次石油冲击带来外汇，属外部注入）↓ 恶化（军费与阿富汗战争 1979– 的持续支出；谷物进口攀升；对波兰等国的补贴义务 1980–）外部注入 → 弃权替代方案空间官方议程中被正式讨论的方案数量与激进程度；改革方案的”温和—激进”分布↓（1965 年柯西金改革在 1968 年后被事实上中止，温和方案退出议程）↓↓（1979 年尝试局限于效率层面；到 1985 年温和方案已不在议程内）持续收缩 → 负债按结构与推广后的规则三，1970 年代的财政改善来自外部注入（石油租金），该分项记为弃权，不参与多数决。有效阻力项为三项，均判负债，判定记为 <strong>3:0（财政项弃权）</strong>。</p><h3 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h3><p>Acemoglu, D. &amp; Robinson, J. A. <em>Economic Origins of Dictatorship and Democracy</em>. Cambridge University Press, 2006. Akerlof, G. A. “Procrastination and Obedience.” <em>American Economic Review</em>, 81(2), 1991. Alesina, A. &amp; Drazen, A. “Why Are Stabilizations Delayed?” <em>American Economic Review</em>, 81(5), 1991. Brunsson, N. <em>The Organization of Hypocrisy: Talk, Decisions and Actions in Organizations</em>. Wiley, 1989. Davies, J. C. “Toward a Theory of Revolution.” <em>American Sociological Review</em>, 27(1), 1962. Dewatripont, M. &amp; Roland, G. “The Virtues of Gradualism and Legitimacy in the Transition to a Market Economy.” <em>Economic Journal</em>, 102(411), 1992. Fernandez, R. &amp; Rodrik, D. “Resistance to Reform: Status Quo Bias in the Presence of Individual-Specific Uncertainty.” <em>American Economic Review</em>, 81(5), 1991. Geddes, B. “What Do We Know About Democratization After Twenty Years?” <em>Annual Review of Political Science</em>, 1999. Geddes, B., Wright, J. &amp; Frantz, E. “Autocratic Breakdown and Regime Transitions: A New Data Set.” <em>Perspectives on Politics</em>, 12(2), 2014, pp. 293–311. Heilmann, S. “From Local Experiments to National Policy: The Origins of China’s Distinctive Policy Process.” <em>The China Journal</em>, 59, 2008, pp. 1–30. Laibson, D. “Golden Eggs and Hyperbolic Discounting.” <em>Quarterly Journal of Economics</em>, 112(2), 1997. Olson, M. <em>The Rise and Decline of Nations</em>. Yale University Press, 1982. Pierson, P. <em>Dismantling the Welfare State?</em> Cambridge University Press, 1994；”Increasing Returns, Path Dependence, and the Study of Politics.” <em>APSR</em>, 94(2), 2000；<em>Politics in Time</em>. Princeton University Press, 2004. Tocqueville, A. de. <em>L’Ancien Régime et la Révolution</em>. 1856. Wilson, J. Q. 关于集中／分散利益与组织政治的分析，见 <em>Political Organizations</em>（Basic Books, 1973；1980 第二版）与 <em>The Politics of Regulation</em>（Basic Books, 1980）。本文仅借用”集中／分散”一半，增量在时间维度与信号维度。<strong>两种出处在本文的不同稿次中曾被分别采用，这一漂移本身说明出处未经核对；读者引用时须自行确认具体版本。</strong> 周雪光：《中国国家治理的制度逻辑》，2017；《基层政府间的”共谋现象”》，2009。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2086500812612810010" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',296)])])}const u=t(g,[["render",a]]);export{d as __pageData,u as default};
